import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
instructions = data[1:]

current_position = 0
valid = True

for i in range(n):
    length, direction = int(instructions[i]), instructions[i + 1]
    if current_position == 0 and direction != "South":
        valid = False
        break
    elif current_position == 20000 and direction != "North":
        valid = False
        break
    if direction == "North":
        current_position -= length
    elif direction == "South":
        current_position += length

if current_position != 0:
    valid = False

if valid:
    print("YES")
else:
    print("NO")
